import string

M = 26
ALPHABET = string.ascii_lowercase


def _validate(a):
    if math_gcd(a, M) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a):
    for x in range(M):
        if (a * x) % M == 1:
            return x
    raise ValueError("a and m must be coprime.")


def _transform(text, a, b, inverse=False):
    out = []
    for char in text.lower():
        if char in ALPHABET:
            i = ALPHABET.index(char)
            if inverse:
                a_inv = _modular_inverse(a)
                i = (a_inv * (i - b)) % M
            else:
                i = (a * i + b) % M
            out.append(ALPHABET[i])
        elif char.isdigit():
            out.append(char)
    return "".join(out)


def encode(plain_text, a, b):
    _validate(a)
    result = _transform(plain_text, a, b)
    return " ".join(result[i : i + 5] for i in range(0, len(result), 5))


def decode(ciphered_text, a, b):
    _validate(a)
    return _transform(ciphered_text, a, b, inverse=True)

